/**
 * Test flow for waitForCondition action
 * Demonstrates waiting for a condition to be met on a record
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testWaitForCondition = Flow(
    {
        $id: Now.ID['test_wait_for_condition_flow'],
        name: 'Test Wait For Condition',
        description: 'Tests the waitForCondition core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_wait_for_condition_trigger'] },
        {
            table: 'incident',
            condition: 'active=true',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        const result = wfa.action(
            action.core.waitForCondition,
            { $id: Now.ID['test_wait_for_condition_action'] },
            {
                table_name: 'incident',
                record: wfa.dataPill(_params.trigger.current.sys_id, 'reference'),
                conditions: 'state=6',
                timeout_duration: Duration({ days: 1 }),
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_wait_for_condition_log'] },
            {
                log_level: 'info',
                log_message: `waitForCondition outputs: state=${wfa.dataPill(result.state, 'string')}`,
            }
        )
    }
)
